// Calculate time filter for last 2 minutes
const now = new Date();
const twoMinutesAgo = new Date(now.getTime() - 2 * 60 * 1000);
const filterTime = twoMinutesAgo.toISOString();

return [{
  json: {
    access_token: $input.first().json.access_token,
    filter_time: filterTime
  }
}];

// Check if we have any detections
const response = $input.first().json;
const resources = response.resources || [];

if (resources.length === 0) {
  // No new detections, stop workflow
  return [];
}

// Get the token from earlier node
const tokenNode = $('Prepare Query').first();
const accessToken = tokenNode.json.access_token;

return [{
  json: {
    detection_ids: resources,
    access_token: accessToken
  }
}];

// Split detections into individual items for processing
const response = $input.first().json;
const detections = response.resources || [];

return detections.map(detection => ({
  json: detection
}));

// Format detection for the security alert webhook
const detection = $input.first().json;
const device = detection.device || {};
const behaviors = detection.behaviors || [];
const firstBehavior = behaviors[0] || {};

const payload = {
  metadata: {
    eventType: 'DetectionSummaryEvent',
    customerIDString: detection.cid || ''
  },
  event: {
    detection_id: detection.detection_id || '',
    created_timestamp: detection.created_timestamp || '',
    severity: detection.max_severity || 0,
    max_severity_displayname: detection.max_severity_displayname || '',
    confidence: detection.max_confidence || 0,
    detect_name: firstBehavior.display_name || firstBehavior.technique || detection.max_severity_displayname || '',
    detect_description: firstBehavior.description || '',
    technique: firstBehavior.technique || '',
    tactic: firstBehavior.tactic || '',
    filepath: firstBehavior.filepath || '',
    filename: firstBehavior.filename || '',
    sha256: firstBehavior.sha256 || '',
    sha1: firstBehavior.sha1 || '',
    md5: firstBehavior.md5 || '',
    cmdline: firstBehavior.cmdline || '',
    command_line: firstBehavior.cmdline || '',
    user_name: firstBehavior.user_name || '',
    process_name: firstBehavior.filename || '',
    process_id: firstBehavior.process_id || '',
    parent_process_name: firstBehavior.parent_details?.parent_process_name || '',
    parent_cmdline: firstBehavior.parent_details?.parent_cmdline || ''
  },
  device: {
    hostname: device.hostname || '',
    device_id: device.device_id || '',
    site_name: (device.groups && device.groups[0]) || '',
    groups: device.groups || [],
    local_ip: device.local_ip || '',
    external_ip: device.external_ip || '',
    os_version: device.os_version || '',
    platform_name: device.platform_name || '',
    machine_user: device.machine_user || ''
  }
};

return [{ json: payload }];
